import React, { useState, useEffect } from 'react';
import { useQuery, useMutation } from '@apollo/client';
import { 
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow, 
  Paper, Tabs, Tab, Box, Typography, Select, MenuItem, FormControl, 
  InputLabel, Button, IconButton, Tooltip, Alert, Snackbar
} from '@mui/material';
import { Add, Edit, Delete, Refresh } from '@mui/icons-material';
import { format } from 'date-fns';
import { 
  GET_ALL_APPOINTMENTS, 
  GET_ALL_CONTACTS, 
  CREATE_APPOINTMENT, 
  UPDATE_APPOINTMENT, 
  DELETE_APPOINTMENT, 
  UPDATE_APPOINTMENT_STATUS, 
  UPDATE_CONTACT_STATUS 
} from '../../graphql/admin';
import AppointmentForm from './AppointmentForm';
import ConfirmationDialog from '../../components/ConfirmationDialog';

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 2 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

function AdminDashboard() {
  const [tabValue, setTabValue] = useState(0);
  const [appointments, setAppointments] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [currentAppointment, setCurrentAppointment] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [appointmentToDelete, setAppointmentToDelete] = useState(null);

  // Fetch data
  const { loading: loadingAppointments, refetch: refetchAppointments } = useQuery(GET_ALL_APPOINTMENTS, {
    onCompleted: (data) => {
      setAppointments(data?.allAppointments || []);
    },
    onError: (error) => {
      console.error('Error fetching appointments:', error);
      setError(`Error loading appointments: ${error.message}`);
    },
    fetchPolicy: 'network-only'
  });

  const { loading: loadingContacts, refetch: refetchContacts } = useQuery(GET_ALL_CONTACTS, {
    onCompleted: (data) => {
      setContacts(data?.allContacts || []);
    },
    onError: (error) => {
      console.error('Error fetching contacts:', error);
      setError(`Error loading contacts: ${error.message}`);
    },
    fetchPolicy: 'network-only'
  });

  // Mutations
  const [createAppointment] = useMutation(CREATE_APPOINTMENT, {
    onCompleted: () => {
      refetchAppointments();
      setSuccess('Appointment created successfully');
      setIsFormOpen(false);
    },
    onError: (error) => {
      setError(`Error creating appointment: ${error.message}`);
    }
  });

  const [updateAppointment] = useMutation(UPDATE_APPOINTMENT, {
    onCompleted: () => {
      refetchAppointments();
      setSuccess('Appointment updated successfully');
      setIsFormOpen(false);
    },
    onError: (error) => {
      setError(`Error updating appointment: ${error.message}`);
    }
  });

  const [deleteAppointment] = useMutation(DELETE_APPOINTMENT, {
    onCompleted: () => {
      refetchAppointments();
      setSuccess('Appointment deleted successfully');
      setDeleteDialogOpen(false);
    },
    onError: (error) => {
      setError(`Error deleting appointment: ${error.message}`);
    }
  });

  const [updateAppointmentStatus] = useMutation(UPDATE_APPOINTMENT_STATUS, {
    onError: (error) => {
      setError(`Error updating status: ${error.message}`);
    }
  });

  const [updateContactStatus] = useMutation(UPDATE_CONTACT_STATUS, {
    onError: (error) => {
      setError(`Error updating status: ${error.message}`);
    }
  });

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleStatusChange = async (id, newStatus, type) => {
    try {
      if (type === 'appointment') {
        // Ensure the status is in the correct format (uppercase string)
        const formattedStatus = typeof newStatus === 'string' 
          ? newStatus.toUpperCase() 
          : newStatus;

        await updateAppointmentStatus({
          variables: {
            appointmentId: id,
            status: formattedStatus
          },
          refetchQueries: [
            { query: GET_ALL_APPOINTMENTS }
          ]
        });

        // Show success message
        setSnackbar({
          open: true,
          message: 'Appointment status updated successfully',
          severity: 'success'
        });

        // Update local state for immediate feedback
        setAppointments(prev => 
          prev.map(appt => 
            appt.id === id ? { ...appt, status: formattedStatus } : appt
          )
        );
      } else if (type === 'contact') {
        await updateContactStatus({
          variables: {
            contactId: id,
            status: newStatus
          }
        });
        // Update local state for immediate feedback
        setContacts(prev => 
          prev.map(contact => 
            contact.id === id ? { ...contact, status: newStatus } : contact
          )
        );
      }
    } catch (error) {
      console.error('Error updating status:', error);
      setError(`Failed to update status: ${error.message}`);
    }
  };

  const handleOpenForm = (appointment = null) => {
    setCurrentAppointment(appointment);
    setIsFormOpen(true);
  };

  const handleCloseForm = () => {
    setIsFormOpen(false);
    setCurrentAppointment(null);
  };

  const handleSaveAppointment = async (appointmentData) => {
    try {
      const input = {
        ...appointmentData,
        id: appointmentData.id || undefined, // Don't send id for new appointments
        appointmentDate: appointmentData.appointmentDate.toISOString()
      };

      if (appointmentData.id) {
        // Update existing appointment
        await updateAppointment({
          variables: { input }
        });
      } else {
        // Create new appointment
        await createAppointment({
          variables: { input }
        });
      }
    } catch (error) {
      console.error('Error saving appointment:', error);
      // Error is handled by the mutation's onError
    }
  };

  const handleDeleteClick = (appointment) => {
    setAppointmentToDelete(appointment);
    setDeleteDialogOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (appointmentToDelete) {
      await deleteAppointment({
        variables: { id: appointmentToDelete.id }
      });
    }
    setDeleteDialogOpen(false);
    setAppointmentToDelete(null);
  };

  const handleCloseSnackbar = () => {
    setError(null);
    setSuccess(null);
  };

  const handleRefresh = () => {
    if (tabValue === 0) {
      refetchAppointments();
    } else {
      refetchContacts();
    }
  };

  const isLoading = loadingAppointments || loadingContacts;

  return (
    <Box sx={{ width: '100%' }}>
      <Box sx={{ borderBottom: 1, borderColor: 'divider', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Tabs value={tabValue} onChange={handleTabChange} aria-label="admin dashboard tabs">
          <Tab label="Appointments" />
          <Tab label="Messages" />
        </Tabs>
        <Box sx={{ pr: 2 }}>
          {tabValue === 0 && (
            <Button
              variant="contained"
              color="primary"
              startIcon={<Add />}
              onClick={() => handleOpenForm()}
              sx={{ mr: 1 }}
            >
              New Appointment
            </Button>
          )}
          <Tooltip title="Refresh">
            <IconButton onClick={handleRefresh} disabled={isLoading}>
              <Refresh />
            </IconButton>
          </Tooltip>
        </Box>
      </Box>

      <TabPanel value={tabValue} index={0}>
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Name</TableCell>
                <TableCell>Email</TableCell>
                <TableCell>Phone</TableCell>
                <TableCell>Service</TableCell>
                <TableCell>Date</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {appointments.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} align="center">
                    No appointments found
                  </TableCell>
                </TableRow>
              ) : (
                appointments.map((appointment) => (
                  <TableRow key={appointment.id}>
                    <TableCell>{`${appointment.firstName} ${appointment.lastName}`}</TableCell>
                    <TableCell>{appointment.email}</TableCell>
                    <TableCell>{appointment.phone}</TableCell>
                    <TableCell>{appointment.service}</TableCell>
                    <TableCell>
                      {format(new Date(appointment.appointmentDate), 'MMM d, yyyy h:mm a')}
                    </TableCell>
                    <TableCell>
                      <FormControl fullWidth size="small">
                        <Select
                          value={appointment.status}
                          onChange={(e) => 
                            handleStatusChange(appointment.id, e.target.value, 'appointment')
                          }
                          size="small"
                        >
                          <MenuItem value="PENDING">Pending</MenuItem>
                          <MenuItem value="CONFIRMED">Confirmed</MenuItem>
                          <MenuItem value="COMPLETED">Completed</MenuItem>
                          <MenuItem value="CANCELLED">Cancelled</MenuItem>
                        </Select>
                      </FormControl>
                    </TableCell>
                    <TableCell>
                      <Tooltip title="Edit">
                        <IconButton 
                          size="small" 
                          onClick={() => handleOpenForm(appointment)}
                          color="primary"
                        >
                          <Edit fontSize="small" />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="Delete">
                        <IconButton 
                          size="small" 
                          onClick={() => handleDeleteClick(appointment)}
                          color="error"
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </TabPanel>

      <TabPanel value={tabValue} index={1}>
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Name</TableCell>
                <TableCell>Email</TableCell>
                <TableCell>Phone</TableCell>
                <TableCell>Subject</TableCell>
                <TableCell>Message</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Created</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {contacts.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} align="center">
                    No messages found
                  </TableCell>
                </TableRow>
              ) : (
                contacts.map((contact) => (
                  <TableRow key={contact.id}>
                    <TableCell>{contact.name}</TableCell>
                    <TableCell>{contact.email}</TableCell>
                    <TableCell>{contact.phone || 'N/A'}</TableCell>
                    <TableCell>{contact.subject}</TableCell>
                    <TableCell sx={{ maxWidth: 300, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {contact.message}
                    </TableCell>
                    <TableCell>
                      <FormControl fullWidth size="small">
                        <Select
                          value={contact.status || 'NEW'}
                          onChange={(e) => 
                            handleStatusChange(contact.id, e.target.value, 'contact')
                          }
                          size="small"
                        >
                          <MenuItem value="NEW">New</MenuItem>
                          <MenuItem value="IN_PROGRESS">In Progress</MenuItem>
                          <MenuItem value="RESOLVED">Resolved</MenuItem>
                          <MenuItem value="CLOSED">Closed</MenuItem>
                        </Select>
                      </FormControl>
                    </TableCell>
                    <TableCell>
                      {format(new Date(contact.createdAt), 'MMM d, yyyy')}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </TabPanel>

      {/* Appointment Form Dialog */}
      <AppointmentForm 
        open={isFormOpen}
        onClose={handleCloseForm}
        appointment={currentAppointment}
        onSave={handleSaveAppointment}
      />

      {/* Delete Confirmation Dialog */}
      <ConfirmationDialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onConfirm={handleConfirmDelete}
        title="Delete Appointment"
        content={`Are you sure you want to delete the appointment for ${appointmentToDelete?.firstName} ${appointmentToDelete?.lastName}?`}
      />

      {/* Snackbar for messages */}
      <Snackbar 
        open={!!error || !!success} 
        autoHideDuration={6000} 
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleCloseSnackbar} 
          severity={error ? 'error' : 'success'} 
          sx={{ width: '100%' }}
        >
          {error || success}
        </Alert>
      </Snackbar>
    </Box>
  );
}

export default AdminDashboard;
